/* ===================== PHB102 ปริมาณสารสัมพันธ์ บทที่ 1 : เนื้อหาสรุป คลังโจทย์ และตัวสร้างโจทย์ =====================
   ค่าที่ใช้ตามชีท: C 12, H 1, N 14, O 16, Na 23, S 32, Cl 35.5, K 39.1, F 19 และ 1 mol = 6.02×10²³ */
const AM={C:12,H:1,N:14,O:16,Na:23,S:32,Cl:35.5,K:39.1,F:19,Mg:24.3,Zn:65.4,Ca:40,Cr:52,Fe:55.8,Cu:63.5,P:31};
const NA=6.02e23;
function parseF(f){const o={};f.replace(/([A-Z][a-z]?)(\d*)/g,(m,e,n)=>{o[e]=(o[e]||0)+(+n||1);});return o;}
function mwOf(f){const o=parseF(f);let s=0;for(const k in o)s+=AM[k]*o[k];return Math.round(s*10)/10;}
const SUB={'0':'₀','1':'₁','2':'₂','3':'₃','4':'₄','5':'₅','6':'₆','7':'₇','8':'₈','9':'₉'};
const SUP={'-':'⁻','0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹'};
/* แปลงเลขท้ายสัญลักษณ์ธาตุเป็นตัวห้อย เช่น C8H9NO2 เป็น C₈H₉NO₂ (เลขสัมประสิทธิ์หน้าสารไม่ถูกแตะ) */
const chemTxt=s=>String(s).replace(/(?<=[A-Z][a-z]?|\))\d+/g,n=>n.split('').map(c=>SUB[c]).join(''));
const sup=e=>String(e).split('').map(c=>SUP[c]||c).join('');
function fmt(x){
  if(!isFinite(x)) return '–'; if(x===0) return '0';
  const e=Math.floor(Math.log10(Math.abs(x))+1e-12);
  if(e>=5||e<=-4){let m=x/Math.pow(10,e),mm=m.toFixed(2),ee=e; if(+mm>=10){mm=(m/10).toFixed(2);ee=e+1;} return mm+'×10'+sup(ee);}
  if(e>=3) return Number(x.toPrecision(3)).toLocaleString('en-US');
  return x.toPrecision(3);
}
const fmtS=x=>{const s=fmt(x);return /×/.test(s)?s:String(+(+s.replace(/,/g,'')).toPrecision(3)).replace(/\B(?=(\d{3})+(?!\d))/g,',');};
const ri=(a,b)=>a+Math.floor(Math.random()*(b-a+1));
const pick=a=>a[Math.floor(Math.random()*a.length)];
const shuf=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const rnd=(a,b,dp)=>+(a+Math.random()*(b-a)).toFixed(dp);

const CHEM_TOPICS={
  mol:{n:'โมล (Mole)',d:'แปลงระหว่างมวล จำนวนอนุภาค ปริมาตรแก๊ส และ mol',pg:4,sec:'mol'},
  pct:{n:'% ความเข้มข้น',d:'%w/v, %w/w และ %v/v',pg:10,sec:'conc'},
  molar:{n:'Molarity',d:'ความเข้มข้นโมลาร์ และการเตรียมสารละลาย',pg:10,sec:'conc'},
  formula:{n:'สูตรเคมี',d:'% องค์ประกอบของธาตุ และสูตรเอมพิริกัล',pg:16,sec:'formula'},
  balance:{n:'ดุลสมการเคมี',d:'หาสัมประสิทธิ์ที่ทำให้อะตอมสองข้างเท่ากัน',pg:17,sec:'equation'},
  limiting:{n:'สารกำหนดปริมาณ',d:'หาสารที่หมดก่อน และผลิตภัณฑ์สูงสุด',pg:18,sec:'reaction'},
  yield:{n:'%yield',d:'ร้อยละของผลิตภัณฑ์',pg:23,sec:'yield'},
  concept:{n:'ทฤษฎีและหลักการ',d:'นิยาม คำย่อ และข้อควรจำ',pg:3,sec:'intro'}
};
const LVN={easy:'ง่าย',mid:'ปานกลาง',hard:'ยาก'};

/* ---------- ตัวช่วยสร้างข้อช้อยส์ ---------- */
function mcq(t,lv,stem,right,wrongs,exp,o){
  const seen=new Set([right]); const ws=[];
  for(const w of wrongs){ if(w==null||seen.has(w)) continue; seen.add(w); ws.push(w); if(ws.length===3) break; }
  if(ws.length<3) return null;
  const opts=shuf([right,...ws]);
  return Object.assign({t,lv,stem,opts,ans:opts.indexOf(right),exp},o||{});
}
/* ตัวลวงเชิงตัวเลข: ใช้ค่าที่ได้จากความผิดพลาดที่พบบ่อย ถ้าไม่ครบเติมด้วยตัวคูณ */
function numQ(t,lv,stem,val,unit,errs,exp,o){
  const f=v=>fmt(v)+(unit?' '+unit:''); const right=f(val);
  const pool=errs.filter(v=>v>0&&isFinite(v)).map(f);
  for(const k of shuf([10,0.1,2,0.5,1.5,100,0.01,3])) pool.push(f(val*k));
  return mcq(t,lv,stem,right,pool,exp,o);
}

const DRUGS=[
  {n:'พาราเซตามอล',f:'C8H9NO2'},{n:'ไอบูโพรเฟน',f:'C13H18O2'},{n:'แอสไพริน',f:'C9H8O4'},{n:'คาเฟอีน',f:'C8H10N4O2'},
  {n:'เมทฟอร์มิน',f:'C4H11N5'},{n:'กลูโคส',f:'C6H12O6'},{n:'อะม็อกซิซิลลิน',f:'C16H19N3O5S'},{n:'โซเดียมคลอไรด์',f:'NaCl'},
  {n:'โซเดียมฟลูออไรด์',f:'NaF'},{n:'กรดอะซิติก',f:'CH3COOH'},{n:'โซเดียมไบคาร์บอเนต',f:'NaHCO3'},{n:'กรดซาลิไซลิก',f:'C7H6O3'},
  {n:'โพแทสเซียมคลอไรด์',f:'KCl'},{n:'โซเดียมไฮดรอกไซด์',f:'NaOH'}
];
const GASES=[{n:'แก๊สออกซิเจน',f:'O2'},{n:'แก๊สคาร์บอนไดออกไซด์',f:'CO2'},{n:'แก๊สไนตรัสออกไซด์ (แก๊สดมสลบ)',f:'N2O'},{n:'แก๊สแอมโมเนีย',f:'NH3'},{n:'แก๊สมีเทน',f:'CH4'},{n:'แก๊สไนโตรเจน',f:'N2'}];
const nm=d=>`${d.n} (${d.f})`;

/* ---------- 1. โมล ---------- */
const G_MOL={
  easy:[
    ()=>{const d=pick(DRUGS),M=mwOf(d.f),n=rnd(0.02,2.5,2),g=+(n*M).toPrecision(3);
      return numQ('mol','easy',`${nm(d)} มวล ${fmtS(g)} g คิดเป็นกี่โมล (MW = ${M} g/mol)`,g/M,'mol',[g*M,M/g,g/NA*1e23,g/22.4],
        [`ใช้สูตร n = g / MW`,`n = ${fmtS(g)} / ${M} = <b>${fmt(g/M)} mol</b>`]);},
    ()=>{const d=pick(DRUGS),M=mwOf(d.f),n=rnd(0.01,1.5,3);
      return numQ('mol','easy',`ต้องการ${nm(d)} จำนวน ${fmtS(n)} mol ต้องชั่งสารกี่กรัม (MW = ${M} g/mol)`,n*M,'g',[n/M,M/n,n*22.4,n*M*10],
        [`จาก n = g / MW จัดรูปได้ g = n × MW`,`g = ${fmtS(n)} × ${M} = <b>${fmt(n*M)} g</b>`]);},
    ()=>{const g=pick(GASES),n=rnd(0.05,3,2);
      return numQ('mol','easy',`${nm(g)} จำนวน ${fmtS(n)} mol มีปริมาตรกี่ลิตรที่ STP`,n*22.4,'L',[n/22.4,22.4/n,n*mwOf(g.f),n*24.5],
        [`แก๊ส 1 mol ที่ STP มีปริมาตร 22.4 L`,`V = n × 22.4 = ${fmtS(n)} × 22.4 = <b>${fmt(n*22.4)} L</b>`]);},
    ()=>{const g=pick(GASES),v=+(rnd(0.05,3,2)*22.4).toPrecision(3);
      return numQ('mol','easy',`${nm(g)} ปริมาตร ${fmtS(v)} L ที่ STP คิดเป็นกี่โมล`,v/22.4,'mol',[v*22.4,22.4/v,v/mwOf(g.f),v/24.5],
        [`ใช้สูตร n = V / 22.4 (ใช้ได้เฉพาะแก๊สที่ STP)`,`n = ${fmtS(v)} / 22.4 = <b>${fmt(v/22.4)} mol</b>`]);},
    ()=>{const d=pick(DRUGS),n=rnd(0.01,2,2);
      return numQ('mol','easy',`${nm(d)} จำนวน ${fmtS(n)} mol มีกี่โมเลกุล`,n*NA,'โมเลกุล',[n*NA/10,n*NA*10,n*6.02e22*mwOf(d.f)/10,NA/n],
        [`1 mol = 6.02×10²³ อนุภาค`,`N = n × 6.02×10²³ = ${fmtS(n)} × 6.02×10²³ = <b>${fmt(n*NA)} โมเลกุล</b>`]);}
  ],
  mid:[
    ()=>{const d=pick(DRUGS),M=mwOf(d.f),N=rnd(1,9,1)*Math.pow(10,pick([21,22,23]));
      return numQ('mol','mid',`${nm(d)} จำนวน ${fmt(N)} โมเลกุล คิดเป็นกี่โมล`,N/NA,'mol',[N/NA*10,N/NA/10,N/NA*M,NA/N],
        [`ใช้สูตร n = N / 6.02×10²³`,`n = ${fmt(N)} / 6.02×10²³ = <b>${fmt(N/NA)} mol</b>`]);},
    ()=>{const d=pick(DRUGS),M=mwOf(d.f),mm=pick([2,5,10,15,20,25,50,75]);
      return numQ('mol','mid',`ต้องการ${nm(d)} จำนวน ${mm} mmol ต้องชั่งสารกี่กรัม (MW = ${M} g/mol)`,mm/1000*M,'g',[mm*M,mm/M,mm/1000/M,mm/100*M],
        [`แปลง mmol เป็น mol ก่อน โดยหาร 1000: ${mm} mmol = ${fmt(mm/1000)} mol`,`g = n × MW = ${fmt(mm/1000)} × ${M} = <b>${fmt(mm/1000*M)} g</b>`]);},
    ()=>{const d=pick(DRUGS),M=mwOf(d.f),g=rnd(0.5,20,2);
      return numQ('mol','mid',`${nm(d)} มวล ${fmtS(g)} g มีกี่โมเลกุล (MW = ${M} g/mol)`,g/M*NA,'โมเลกุล',[g*NA,g*M*NA/1e4,g/M*NA/10,g/M*NA*10],
        [`ขั้นที่ 1 หา mol: n = ${fmtS(g)} / ${M} = ${fmt(g/M)} mol`,`ขั้นที่ 2 คูณเลขอะโวกาโดร: ${fmt(g/M)} × 6.02×10²³ = <b>${fmt(g/M*NA)} โมเลกุล</b>`]);},
    ()=>{const g=pick(GASES),M=mwOf(g.f),m=+(rnd(0.1,3,2)*M).toPrecision(3);
      return numQ('mol','mid',`${nm(g)} มวล ${fmtS(m)} g มีปริมาตรกี่ลิตรที่ STP (MW = ${M} g/mol)`,m/M*22.4,'L',[m*22.4,m/22.4,m/M,M/m*22.4],
        [`ขั้นที่ 1 หา mol: n = ${fmtS(m)} / ${M} = ${fmt(m/M)} mol`,`ขั้นที่ 2 V = n × 22.4 = <b>${fmt(m/M*22.4)} L</b>`]);}
  ],
  hard:[
    ()=>{const d=pick(DRUGS),M=mwOf(d.f),N=rnd(1,9,1)*Math.pow(10,pick([21,22,23]));
      return numQ('mol','hard',`${nm(d)} จำนวน ${fmt(N)} โมเลกุล มีมวลกี่กรัม (MW = ${M} g/mol)`,N/NA*M,'g',[N/NA,N/NA/M,N/NA*M*10,N/NA*M/10],
        [`ขั้นที่ 1 หา mol: n = ${fmt(N)} / 6.02×10²³ = ${fmt(N/NA)} mol`,`ขั้นที่ 2 g = n × MW = ${fmt(N/NA)} × ${M} = <b>${fmt(N/NA*M)} g</b>`]);},
    ()=>{const g=pick(GASES),M=mwOf(g.f),v=+(rnd(0.1,4,2)*22.4).toPrecision(3);
      return numQ('mol','hard',`${nm(g)} ปริมาตร ${fmtS(v)} L ที่ STP มีมวลกี่กรัม (MW = ${M} g/mol)`,v/22.4*M,'g',[v*M,v/22.4,v/M,v*22.4/M],
        [`ขั้นที่ 1 หา mol: n = ${fmtS(v)} / 22.4 = ${fmt(v/22.4)} mol`,`ขั้นที่ 2 g = n × MW = ${fmt(v/22.4)} × ${M} = <b>${fmt(v/22.4*M)} g</b>`]);},
    ()=>{const g=pick(GASES),v=+(rnd(0.1,4,2)*22.4).toPrecision(3);
      return numQ('mol','hard',`${nm(g)} ปริมาตร ${fmtS(v)} L ที่ STP มีกี่โมเลกุล`,v/22.4*NA,'โมเลกุล',[v*NA,v/22.4*NA/10,v/22.4*NA*10,v*22.4*NA/100],
        [`ขั้นที่ 1 หา mol: n = ${fmtS(v)} / 22.4 = ${fmt(v/22.4)} mol`,`ขั้นที่ 2 N = n × 6.02×10²³ = <b>${fmt(v/22.4*NA)} โมเลกุล</b>`]);}
  ]
};

/* ---------- 2. % ความเข้มข้น ---------- */
const WV=[['คลอเฮกซิดีน',[0.05,0.2,2,4]],['กลูโคส',[5,10,50]],['โซเดียมคลอไรด์',[0.45,0.9,3]],['โพวิโดนไอโอดีน',[7.5,10]],['ลิโดเคน',[1,2]]];
const WW=[['ไฮโดรคอร์ติโซน','ครีม',[0.5,1,2.5]],['กรดซาลิไซลิก','ขี้ผึ้ง',[2,5,10]],['ซิงก์ออกไซด์','ครีม',[10,15,20]],['เมนทอล','เจล',[1,2,5]]];
const G_PCT={
  easy:[
    ()=>{const [n,ps]=pick(WV),p=pick(ps),v=pick([100,200,250,400,500,750]);
      return numQ('pct','easy',`ต้องการเตรียมสารละลาย${n} ${p}% w/v ปริมาตร ${v} mL ต้องใช้${n}กี่กรัม`,p*v/100,'g',[p*v,v/p,p*v/1000,100*p/v],
        [`${p}% w/v หมายถึงมีตัวถูกละลาย ${p} g ในสารละลาย 100 mL`,`มวล = ${p} × ${v} / 100 = <b>${fmt(p*v/100)} g</b>`]);},
    ()=>{const [n]=pick(WV),g=rnd(0.5,20,1),v=pick([100,200,250,400,500]);
      return numQ('pct','easy',`มี${n} ${fmtS(g)} g ละลายน้ำจนได้ปริมาตรทั้งหมด ${v} mL มีความเข้มข้นกี่ % w/v`,g/v*100,'% w/v',[g/v,v/g,g*v/100,g/v*1000],
        [`%w/v = (มวลตัวถูกละลาย g / ปริมาตรสารละลาย mL) × 100`,`= (${fmtS(g)} / ${v}) × 100 = <b>${fmt(g/v*100)}% w/v</b>`]);},
    ()=>{const [n,k]=pick(WW),tot=pick([30,50,60,120,150,200]),g=+(tot*pick([0.01,0.02,0.05,0.1,0.125,0.2])).toPrecision(3);
      return numQ('pct','easy',`${k}ขนาด ${tot} g มี${n}อยู่ ${fmtS(g)} g มีความเข้มข้นกี่ % w/w`,g/tot*100,'% w/w',[g/tot,tot/g,g/(tot-g)*100*1.37,g*tot/100],
        [`%w/w = (มวลตัวยา g / มวลทั้งหมด g) × 100`,`= (${fmtS(g)} / ${tot}) × 100 = <b>${fmt(g/tot*100)}% w/w</b>`]);}
  ],
  mid:[
    ()=>{const p=pick([40,50,60,70,75,80]),v=pick([100,150,250,400,500,750]);
      return numQ('pct','mid',`ต้องการเตรียมเอทานอล ${p}% v/v ปริมาตรสุดท้าย ${v} mL ต้องใช้เอทานอลบริสุทธิ์ (100%) กี่ mL`,p*v/100,'mL',[v-p*v/100,v*100/p,p*v/1000,v/p],
        [`${p}% v/v หมายถึงมีเอทานอล ${p} mL ในสารละลาย 100 mL`,`ปริมาตร = ${p} × ${v} / 100 = <b>${fmt(p*v/100)} mL</b> แล้วเติมน้ำจนครบ ${v} mL`]);},
    ()=>{const [n,ps]=pick(WV),p=pick(ps),L=pick([1,1.5,2,2.5,5]);
      return numQ('pct','mid',`ต้องการสารละลาย${n} ${p}% จำนวน ${L} L ต้องชั่ง${n}กี่กรัม`,p*L*10,'g',[p*L,p*L/100,p*L*100,L*1000/p],
        [`โจทย์บอกแค่ % ของสารละลาย ให้ถือเป็น %w/v คือ ${p} g ต่อ 100 mL`,`แปลงปริมาตร ${L} L = ${L*1000} mL`,`มวล = ${p} × ${L*1000} / 100 = <b>${fmt(p*L*10)} g</b>`]);},
    ()=>{const [n,k,ps]=pick(WW),p=pick(ps),tot=pick([15,30,50,100,250,500]);
      return numQ('pct','mid',`ต้องการเตรียม${k}${n} ${p}% w/w จำนวน ${tot} g ต้องใช้${n}กี่กรัม`,p*tot/100,'g',[p*tot,tot/p,tot-p*tot/100,p*tot/1000],
        [`${p}% w/w หมายถึงมีตัวยา ${p} g ใน${k} 100 g`,`มวลตัวยา = ${p} × ${tot} / 100 = <b>${fmt(p*tot/100)} g</b>`]);}
  ],
  hard:[
    ()=>{const [n,ps]=pick(WV),p=pick(ps),g=pick([1,2.5,5,10,20,45]);
      return numQ('pct','hard',`มี${n} ${g} g ต้องการเตรียมสารละลาย ${p}% w/v จะเตรียมได้ปริมาตรกี่ mL`,g*100/p,'mL',[g*p,g*p/100,g/p,g*1000/p],
        [`${p}% w/v คือ ${p} g ต่อ 100 mL`,`ปริมาตร = ${g} × 100 / ${p} = <b>${fmt(g*100/p)} mL</b>`]);},
    ()=>{const c1=pick([70,90,95]),c2=pick([10,20,30,40,50]),v2=pick([100,200,250,500]);
      return numQ('pct','hard',`มีแอลกอฮอล์ ${c1}% v/v ต้องการเจือจางให้ได้ ${c2}% v/v ปริมาตร ${v2} mL ต้องตวงแอลกอฮอล์ ${c1}% มากี่ mL`,c2*v2/c1,'mL',[c1*v2/c2,c2*v2/100,v2-c2*v2/c1,c1*c2/v2],
        [`ใช้สูตรเจือจาง C₁V₁ = C₂V₂`,`${c1} × V₁ = ${c2} × ${v2}`,`V₁ = ${c2*v2} / ${c1} = <b>${fmt(c2*v2/c1)} mL</b>`]);}
  ]
};

/* ---------- 3. Molarity ---------- */
const G_MOLAR={
  easy:[
    ()=>{const d=pick(DRUGS),n=rnd(0.05,1.5,2),v=pick([100,200,250,400,500,750]);
      return numQ('molar','easy',`มี${nm(d)} ${fmtS(n)} mol ละลายน้ำจนได้ปริมาตร ${v} mL มีความเข้มข้นกี่ M`,n/(v/1000),'M',[n/v,n*v/1000,v/1000/n,n/(v/100)],
        [`แปลงปริมาตรเป็นลิตร: ${v} mL = ${v/1000} L`,`M = mol / L = ${fmtS(n)} / ${v/1000} = <b>${fmt(n/(v/1000))} M</b>`]);},
    ()=>{const d=pick(DRUGS),c=pick([0.05,0.1,0.2,0.25,0.5,1,2]),v=pick([50,100,150,250,400,500]);
      return numQ('molar','easy',`สารละลาย${nm(d)} ${c} M ปริมาตร ${v} mL มีตัวถูกละลายกี่โมล`,c*v/1000,'mol',[c*v,c/v*1000,v/c/1000,c*v/100],
        [`ใช้สูตร n = CV / 1000 (V หน่วย mL)`,`n = ${c} × ${v} / 1000 = <b>${fmt(c*v/1000)} mol</b>`]);}
  ],
  mid:[
    ()=>{const d=pick(DRUGS),M=mwOf(d.f),v=pick([100,200,250,300,500]),g=+(M*pick([0.02,0.05,0.1,0.15,0.2])).toPrecision(3);
      return numQ('molar','mid',`ชั่ง${nm(d)} ${fmtS(g)} g ละลายน้ำจนมีปริมาตรสุดท้าย ${v} mL สารละลายนี้เข้มข้นกี่ M (MW = ${M} g/mol)`,g/M/(v/1000),'M',[g/M/v,g/M,g/(v/1000),g*M/(v/1000)/1000],
        [`ขั้นที่ 1 หา mol: ${fmtS(g)} / ${M} = ${fmt(g/M)} mol`,`ขั้นที่ 2 หารด้วยปริมาตรเป็นลิตร: ${fmt(g/M)} / ${v/1000} = <b>${fmt(g/M/(v/1000))} M</b>`]);},
    ()=>{const d=pick(DRUGS),M=mwOf(d.f),c=pick([0.05,0.1,0.2,0.25,0.5]),v=pick([100,250,500,1000]);
      return numQ('molar','mid',`ต้องการเตรียมสารละลาย${nm(d)} ${c} M ปริมาตร ${v} mL ต้องชั่งสารกี่กรัม (MW = ${M} g/mol)`,c*v/1000*M,'g',[c*v*M,c*v/1000,c*M,c*v/1000/M],
        [`ขั้นที่ 1 หา mol: n = CV / 1000 = ${c} × ${v} / 1000 = ${fmt(c*v/1000)} mol`,`ขั้นที่ 2 g = n × MW = ${fmt(c*v/1000)} × ${M} = <b>${fmt(c*v/1000*M)} g</b>`]);}
  ],
  hard:[
    ()=>{const d=pick(DRUGS),M=mwOf(d.f),c=pick([0.1,0.2,0.25,0.5,1]),g=+(M*pick([0.01,0.025,0.05,0.1])).toPrecision(3);
      return numQ('molar','hard',`ต้องการ${nm(d)} ${fmtS(g)} g จากสารละลายเข้มข้น ${c} M ต้องตวงสารละลายกี่ mL (MW = ${M} g/mol)`,g/M/c*1000,'mL',[g/M/c,g/c*1000/100,g*c/M*1000,g/M*c*1000],
        [`ขั้นที่ 1 หา mol ที่ต้องการ: ${fmtS(g)} / ${M} = ${fmt(g/M)} mol`,`ขั้นที่ 2 จาก n = CV / 1000 ได้ V = n × 1000 / C`,`V = ${fmt(g/M)} × 1000 / ${c} = <b>${fmt(g/M/c*1000)} mL</b>`]);},
    ()=>{const d=pick([{n:'โซเดียมคลอไรด์',f:'NaCl'},{n:'กลูโคส',f:'C6H12O6'},{n:'โพแทสเซียมคลอไรด์',f:'KCl'}]),M=mwOf(d.f),p=pick([0.9,5,10,3]);
      return numQ('molar','hard',`สารละลาย${nm(d)} ${p}% w/v มีความเข้มข้นกี่ M (MW = ${M} g/mol)`,p*10/M,'M',[p/M,p*100/M,p*M/100,p*10*M/1000],
        [`${p}% w/v คือ ${p} g ใน 100 mL จึงเท่ากับ ${fmt(p*10)} g ใน 1 L`,`mol ใน 1 L = ${fmt(p*10)} / ${M} = ${fmt(p*10/M)} mol`,`ความเข้มข้น = <b>${fmt(p*10/M)} M</b>`]);}
  ]
};

