const G_FORMULA={
  easy:[
    ()=>{const [m,e]=pick(EMP); const ws=shuf(EMP.map(x=>x[1]).filter(x=>x!==e)).slice(0,2).concat([m]);
      return mcq('formula','easy',`สูตรเอมพิริกัลของ ${m} คือข้อใด`,e,ws,
        [`สูตรเอมพิริกัลคืออัตราส่วนโดยโมลอย่างต่ำที่สุดของธาตุ`,`ทอนเลขตัวห้อยของ ${m} ด้วยตัวหารร่วมมากจนทอนต่อไม่ได้ ได้ <b>${e}</b>`]);},
    ()=>{const d=pick(DRUGS),o=parseF(d.f),M=mwOf(d.f);
      const parts=Object.keys(o).map(k=>`${k} ${o[k]} × ${AM[k]} = ${fmt(o[k]*AM[k])}`);
      return numQ('formula','easy',`มวลโมเลกุลของ${nm(d)} เท่ากับเท่าใด`,M,'g/mol',[M+AM.O,M-AM.H*2,M+AM.C,Object.keys(o).reduce((s,k)=>s+AM[k],0)],
        [`รวมมวลอะตอมของทุกธาตุตามจำนวนในสูตร`,parts.join(' · '),`รวม = <b>${fmt(M)} g/mol</b>`]);}
  ],
  mid:[
    ()=>{const d=pick(DRUGS.filter(x=>Object.keys(parseF(x.f)).length>=2)),o=parseF(d.f),M=mwOf(d.f),el=pick(Object.keys(o)),v=o[el]*AM[el]/M*100;
      return numQ('formula','mid',`${nm(d)} มีธาตุ ${el} อยู่ร้อยละเท่าใดโดยมวล (MW = ${M} g/mol)`,v,'%',[AM[el]/M*100===v?v*1.5:AM[el]/M*100,o[el]/Object.values(o).reduce((a,b)=>a+b,0)*100,100-v,M/(o[el]*AM[el])],
        [`% ธาตุ = (มวลของธาตุนั้นในสูตร / มวลโมเลกุล) × 100`,`มวลของ ${el} ในสูตร = ${o[el]} × ${AM[el]} = ${fmt(o[el]*AM[el])}`,`% ${el} = (${fmt(o[el]*AM[el])} / ${M}) × 100 = <b>${fmt(v)}%</b>`]);}
  ],
  hard:[
    ()=>{const x=pick(EMPP); const rows=x.e.map(([el,p])=>({el,p,mol:p/AM[el]})); const mn=Math.min(...rows.map(r=>r.mol));
      return mcq('formula','hard',`สารชนิดหนึ่งประกอบด้วย ${x.e.map(([el,p])=>`${el} ${p}%`).join(', ')} โดยมวล สูตรเอมพิริกัลคือข้อใด`,x.r,x.w,
        [`ขั้นที่ 1 สมมติสาร 100 g ดังนั้น % ของธาตุคือกรัมของธาตุ`,
         `ขั้นที่ 2 เปลี่ยนกรัมเป็น mol: ${rows.map(r=>`${r.el} = ${r.p} / ${AM[r.el]} = ${fmt(r.mol)}`).join(' · ')}`,
         `ขั้นที่ 3 หารด้วยค่าที่น้อยที่สุด (${fmt(mn)}): ${rows.map(r=>`${r.el} = ${fmt(r.mol/mn)}`).join(' · ')}`,
         `ขั้นที่ 4 ถ้ายังไม่ลงตัวให้คูณด้วยเลขเดียวกันจนเป็นจำนวนเต็ม ได้ <b>${x.r}</b>`]);}
  ]
};

/* ---------- 5. ดุลสมการ ---------- */
const EQS=[
  {k:'การสังเคราะห์ (Combination)',l:['N2','H2'],r:['NH3'],c:[1,3,2]},
  {k:'การสลายตัว (Decomposition)',l:['CaCO3'],r:['CaO','CO2'],c:[1,1,1]},
  {k:'เผาไหม้ไฮโดรคาร์บอน',l:['CH4','O2'],r:['CO2','H2O'],c:[1,2,1,2]},
  {k:'เผาไหม้แอลเคน',l:['C4H10','O2'],r:['CO2','H2O'],c:[2,13,8,10]},
  {k:'Double displacement',l:['AgNO3','NaCl'],r:['AgCl','NaNO3'],c:[1,1,1,1]},
  {k:'Neutralization (กรด-เบส)',l:['H2SO4','NaOH'],r:['Na2SO4','H2O'],c:[1,2,1,2]},
  {k:'การสลายตัวด้วยความร้อน',l:['NH4NO3'],r:['N2O','H2O'],c:[1,1,2]},
  {k:'ปฏิกิริยากับโลหะแอลคาไล',l:['K','Br2'],r:['KBr'],c:[2,1,2]},
  {k:'Precipitation (ตกตะกอน)',l:['BaCl2','Na2SO4'],r:['BaSO4','NaCl'],c:[1,1,1,2]},
  {k:'Single displacement',l:['Mg','HCl'],r:['MgCl2','H2'],c:[1,2,1,1]},
  {k:'เผาไหม้ไฮโดรคาร์บอน',l:['C3H8','O2'],r:['CO2','H2O'],c:[1,5,3,4]},
  {k:'เผาไหม้แอลเคน',l:['C2H6','O2'],r:['CO2','H2O'],c:[2,7,4,6]},
  {k:'การสังเคราะห์ (Combination)',l:['H2','O2'],r:['H2O'],c:[2,1,2]},
  {k:'การสังเคราะห์ (Combination)',l:['Al','O2'],r:['Al2O3'],c:[4,3,2]},
  {k:'การสลายตัว (Decomposition)',l:['KClO3'],r:['KCl','O2'],c:[2,2,3]},
  {k:'Neutralization (กรด-เบส)',l:['HCl','Ca(OH)2'],r:['CaCl2','H2O'],c:[2,1,1,2]},
  {k:'เผาไหม้กลูโคส',l:['C6H12O6','O2'],r:['CO2','H2O'],c:[1,6,6,6]},
  {k:'Single displacement',l:['Zn','HCl'],r:['ZnCl2','H2'],c:[1,2,1,1]}
];
const eqStr=(q,c)=>{const sp=[...q.l,...q.r]; const t=(s,i)=>(c?(c[i]===1?'':c[i]):'__')+s;
  return q.l.map((s,i)=>t(s,i)).join(' + ')+' → '+q.r.map((s,i)=>t(s,i+q.l.length)).join(' + ');};
function gBalance(lv,idx){
  const q=idx!=null?EQS[idx]:pick(lv==='easy'?EQS.filter(x=>Math.max(...x.c)<=3):lv==='hard'?EQS.filter(x=>Math.max(...x.c)>=5):EQS);
  const sp=[...q.l,...q.r], sum=q.c.reduce((a,b)=>a+b,0);
  const expl=[`ดุลธาตุในสารประกอบก่อน (โลหะก่อนอโลหะ) แล้วดุลธาตุอิสระเป็นอันดับสุดท้าย เปลี่ยนได้เฉพาะสัมประสิทธิ์หน้าสาร ห้ามเปลี่ยนตัวห้อย`,
    `สมการที่ดุลแล้ว: <b>${chemTxt(eqStr(q,q.c))}</b>`,`นับอะตอมแต่ละธาตุทั้งซ้ายและขวาเพื่อตรวจอีกรอบ`];
  if(lv==='hard'||Math.random()<.4){
    return mcq('balance',lv||'mid',`${q.k}\n${eqStr(q)}\nเมื่อดุลสมการแล้ว ผลรวมของสัมประสิทธิ์ทุกตัวเท่ากับเท่าใด`,String(sum),[String(sum+1),String(sum-1),String(sum+2),String(sp.length),String(sum*2)],
      [...expl,`ผลรวมสัมประสิทธิ์ = ${q.c.join(' + ')} = <b>${sum}</b>`]);
  }
  const right=q.c.join(' : '); const ws=new Set();
  let guard=0; while(ws.size<5&&guard++<60){ const c=q.c.slice(); const i=ri(0,c.length-1); c[i]=Math.max(1,c[i]+pick([-1,1,1,2])); if(Math.random()<.4){const j=ri(0,c.length-1);c[j]=Math.max(1,c[j]+pick([-1,1]));} const s=c.join(' : '); if(s!==right) ws.add(s); }
  return mcq('balance',lv||'mid',`${q.k}\n${eqStr(q)}\nสัมประสิทธิ์ที่ทำให้สมการดุล เรียงจากซ้ายไปขวา คือข้อใด`,right,[...ws],expl);
}
const G_BALANCE={easy:[()=>gBalance('easy')],mid:[()=>gBalance('mid')],hard:[()=>gBalance('hard')]};

/* ---------- 6. สารกำหนดปริมาณ ---------- */
const RX=[
  {eq:'C6H5NH2 + CH3COCl → C8H9NO2 + HCl',a:['aniline',93,1],b:['acetyl chloride',78.5,1],p:['พาราเซตามอล',151,1]},
  {eq:'C7H6O3 + C4H6O3 → C9H8O4 + CH3COOH',a:['กรดซาลิไซลิก',138,1],b:['กรดอะซิติกแอนไฮไดรด์',102,1],p:['แอสไพริน',180,1]},
  {eq:'C4H11N5 + HCl → C4H12N5Cl',a:['เมทฟอร์มิน',129,1],b:['HCl',36.5,1],p:['Metformin HCl',165.5,1]},
  {eq:'C7H6O3 + NaHCO3 → C7H5O3Na + CO2 + H2O',a:['กรดซาลิไซลิก',138,1],b:['NaHCO3',84,1],p:['โซเดียมซาลิไซเลต',160,1]},
  {eq:'N2 + 3H2 → 2NH3',a:['N2',28,1],b:['H2',2,3],p:['NH3',17,2]},
  {eq:'Zn + 2HCl → ZnCl2 + H2',a:['Zn',65.4,1],b:['HCl',36.5,2],p:['ZnCl2',136.4,1]},
  {eq:'CH4 + 2O2 → CO2 + 2H2O',a:['CH4',16,1],b:['O2',32,2],p:['CO2',44,1]},
  {eq:'2H2 + O2 → 2H2O',a:['H2',2,2],b:['O2',32,1],p:['H2O',18,2]},
  {eq:'Mg + 2HCl → MgCl2 + H2',a:['Mg',24.3,1],b:['HCl',36.5,2],p:['MgCl2',95.3,1]},
  {eq:'C3H8O3 + 3HNO3 → C3H5N3O9 + 3H2O',a:['กลีเซอรอล',92,1],b:['HNO3',63,3],p:['ไนโทรกลีเซอรีน',227,1]}
];
function rxCalc(r,ga,gb){const na=ga/r.a[1],nb=gb/r.b[1],ra=na/r.a[2],rb=nb/r.b[2],lim=ra<=rb?'a':'b',x=Math.min(ra,rb);return {na,nb,ra,rb,lim,x,gp:x*r.p[2]*r.p[1]};}
function rxMasses(r){ for(let i=0;i<40;i++){ const ga=+(r.a[1]*rnd(0.02,0.2,3)*r.a[2]).toPrecision(3), gb=+(r.b[1]*rnd(0.02,0.2,3)*r.b[2]).toPrecision(3), c=rxCalc(r,ga,gb); const ratio=c.ra/c.rb; if(ratio<0.87||ratio>1.15) return {ga,gb,c}; } const ga=+(r.a[1]*0.05*r.a[2]).toPrecision(3), gb=+(r.b[1]*0.09*r.b[2]).toPrecision(3); return {ga,gb,c:rxCalc(r,ga,gb)}; }
const rxSteps=(r,ga,gb,c)=>[
  `ขั้นที่ 1 หา mol ของสารตั้งต้นแต่ละตัว: ${r.a[0]} = ${fmtS(ga)} / ${r.a[1]} = ${fmt(c.na)} mol และ ${r.b[0]} = ${fmtS(gb)} / ${r.b[1]} = ${fmt(c.nb)} mol`,
  `ขั้นที่ 2 หารด้วยสัมประสิทธิ์หน้าสาร: ${r.a[0]} = ${fmt(c.na)} / ${r.a[2]} = ${fmt(c.ra)} และ ${r.b[0]} = ${fmt(c.nb)} / ${r.b[2]} = ${fmt(c.rb)}`,
  `ตัวที่ได้ค่าน้อยกว่าคือสารกำหนดปริมาณ ดังนั้น <b>${r[c.lim][0]}</b> เป็นสารกำหนดปริมาณ`];
const G_LIMITING={
  easy:[
    ()=>{const r=pick(RX.filter(x=>x.b[2]>1||x.a[2]>1)); const na=rnd(0.1,0.9,3), nb=+(na*r.b[2]/r.a[2]*pick([0.6,0.75,0.85,1.3,1.6,2.2])).toPrecision(3), ra=na/r.a[2], rb=nb/r.b[2], lim=ra<=rb?r.a[0]:r.b[0], oth=ra<=rb?r.b[0]:r.a[0];
      return mcq('limiting','easy',`ปฏิกิริยา ${r.eq}\nเริ่มต้นมี ${r.a[0]} ${fmtS(na)} mol และ ${r.b[0]} ${fmtS(nb)} mol สารกำหนดปริมาณคือสารใด`,lim,[oth,'ทั้งสองตัวหมดพร้อมกันพอดี',r.p[0]],
        [`เอา mol เริ่มต้นหารด้วยสัมประสิทธิ์หน้าสาร ห้ามดูแค่ mol ดิบ`,`${r.a[0]} = ${fmtS(na)} / ${r.a[2]} = ${fmt(ra)} และ ${r.b[0]} = ${fmtS(nb)} / ${r.b[2]} = ${fmt(rb)}`,`ตัวที่ได้ค่าน้อยกว่าคือ <b>${lim}</b> จึงเป็นสารกำหนดปริมาณ`]);}
  ],
  mid:[
    ()=>{const r=pick(RX),{ga,gb,c}=rxMasses(r); const lim=r[c.lim][0], oth=r[c.lim==='a'?'b':'a'][0];
      return mcq('limiting','mid',`ปฏิกิริยา ${r.eq}\nใช้ ${r.a[0]} ${fmtS(ga)} g (MW = ${r.a[1]}) และ ${r.b[0]} ${fmtS(gb)} g (MW = ${r.b[1]}) สารกำหนดปริมาณคือสารใด`,lim,[oth,'ทั้งสองตัวหมดพร้อมกันพอดี',r.p[0]],rxSteps(r,ga,gb,c));}
  ],
  hard:[
    ()=>{const r=pick(RX),{ga,gb,c}=rxMasses(r); const o=c.lim==='a'?c.rb:c.ra;
      return numQ('limiting','hard',`ปฏิกิริยา ${r.eq}\nใช้ ${r.a[0]} ${fmtS(ga)} g (MW = ${r.a[1]}) และ ${r.b[0]} ${fmtS(gb)} g (MW = ${r.b[1]}) จะได้ ${r.p[0]} (MW = ${r.p[1]}) สูงสุดกี่กรัม`,c.gp,'g',[o*r.p[2]*r.p[1],c.x*r.p[1]*(r.p[2]===1?2:1),ga+gb,Math.min(c.na,c.nb)*r.p[1]*1.21],
        [...rxSteps(r,ga,gb,c),`ขั้นที่ 3 เทียบ mol จากสารกำหนดปริมาณ: ได้ ${r.p[0]} = ${fmt(c.x)} × ${r.p[2]} = ${fmt(c.x*r.p[2])} mol`,`ขั้นที่ 4 แปลงเป็นกรัม: ${fmt(c.x*r.p[2])} × ${r.p[1]} = <b>${fmt(c.gp)} g</b>`]);}
  ]
};

/* ---------- 7. %yield ---------- */
const G_YIELD={
  easy:[
    ()=>{const th=rnd(2,12,2),ac=+(th*rnd(0.55,0.95,3)).toFixed(2),d=pick(['ลอราทาดีน','chlorpheniramine maleate','แอสไพริน','พาราเซตามอล','โซเดียมซาลิไซเลต']);
      return numQ('yield','easy',`การสังเคราะห์${d} คำนวณผลผลิตทางทฤษฎีได้ ${fmtS(th)} g แต่ผลิตได้จริง ${fmtS(ac)} g มี %yield เท่าใด`,ac/th*100,'%',[th/ac*100,(th-ac)/th*100,ac/th,ac*th],
        [`%yield = (ผลผลิตจริง / ผลผลิตทางทฤษฎี) × 100`,`= (${fmtS(ac)} / ${fmtS(th)}) × 100 = <b>${fmt(ac/th*100)}%</b>`,`%yield ต้องไม่เกิน 100% ถ้าเกินแปลว่าสลับตัวเศษกับตัวส่วน`]);}
  ],
  mid:[
    ()=>{const r=pick(RX.slice(0,4)),ga=+(r.a[1]*rnd(0.02,0.06,3)).toPrecision(3),th=ga/r.a[1]*r.p[1],ac=+(th*rnd(0.6,0.95,3)).toFixed(2);
      return numQ('yield','mid',`ปฏิกิริยา (ดุลแล้ว) ${r.eq}\nใช้ ${r.a[0]} ${fmtS(ga)} g (MW = ${r.a[1]}) ทำปฏิกิริยากับ ${r.b[0]} มากเกินพอ ได้ ${r.p[0]} จริง ${fmtS(ac)} g มี %yield เท่าใด (MW ผลิตภัณฑ์ = ${r.p[1]})`,ac/th*100,'%',[th/ac*100,ac/ga*100,(th-ac)/th*100,ga/ac*10],
        [`ขั้นที่ 1 ผลผลิตทางทฤษฎี = (${fmtS(ga)} / ${r.a[1]}) × ${r.p[1]} = ${fmt(th)} g`,`ขั้นที่ 2 %yield = (${fmtS(ac)} / ${fmt(th)}) × 100 = <b>${fmt(ac/th*100)}%</b>`]);},
    ()=>{const th=rnd(3,15,2),p=pick([62,70,75,80,85,88,92]);
      return numQ('yield','mid',`ผลผลิตทางทฤษฎีของยาชนิดหนึ่งเท่ากับ ${fmtS(th)} g ถ้ากระบวนการผลิตมี %yield ${p}% จะได้ผลผลิตจริงกี่กรัม`,th*p/100,'g',[th*100/p,th*(100-p)/100,th*p,th/p],
        [`จาก %yield = (จริง / ทฤษฎี) × 100 จัดรูปได้ จริง = ทฤษฎี × %yield / 100`,`= ${fmtS(th)} × ${p} / 100 = <b>${fmt(th*p/100)} g</b>`]);}
  ],
  hard:[
    ()=>{const r=pick(RX),{ga,gb,c}=rxMasses(r),ac=+(c.gp*rnd(0.6,0.93,3)).toPrecision(3); const o=(c.lim==='a'?c.rb:c.ra)*r.p[2]*r.p[1];
      return numQ('yield','hard',`ปฏิกิริยา ${r.eq}\nใช้ ${r.a[0]} ${fmtS(ga)} g (MW = ${r.a[1]}) และ ${r.b[0]} ${fmtS(gb)} g (MW = ${r.b[1]}) ได้ ${r.p[0]} (MW = ${r.p[1]}) จริง ${fmtS(ac)} g มี %yield เท่าใด`,ac/c.gp*100,'%',[ac/o*100,c.gp/ac*100,ac/(ga+gb)*100,(c.gp-ac)/c.gp*100],
        [...rxSteps(r,ga,gb,c),`ขั้นที่ 3 ผลผลิตทางทฤษฎี = ${fmt(c.x)} × ${r.p[2]} × ${r.p[1]} = ${fmt(c.gp)} g`,`ขั้นที่ 4 %yield = (${fmtS(ac)} / ${fmt(c.gp)}) × 100 = <b>${fmt(ac/c.gp*100)}%</b>`]);}
  ]
};

