function gConcept(lv){ const pool=lv&&lv!=='mix'?CONCEPTS.filter(c=>c.lv===lv):CONCEPTS; const c=pick(pool.length?pool:CONCEPTS); return conceptQ(c); }
function conceptQ(c){ return mcq('concept',c.lv,c.q,c.right,shuf(c.wrongs),[c.why],{cid:CONCEPTS.indexOf(c)}); }

const GEN={mol:G_MOL,pct:G_PCT,molar:G_MOLAR,formula:G_FORMULA,balance:G_BALANCE,limiting:G_LIMITING,yield:G_YIELD,
  concept:{easy:[()=>gConcept('easy')],mid:[()=>gConcept('mid')],hard:[()=>gConcept('hard')]}};
function genQ(topic,lv){
  const t=topic==='all'?pick(Object.keys(GEN)):topic; const l=lv==='mix'||!lv?pick(['easy','mid','mid','hard']):lv;
  for(let i=0;i<30;i++){ const g=pick(GEN[t][l]||GEN[t].mid); const q=g(); if(q) return q; }
  return gConcept();
}
function genSet(topic,lv,n){ const out=[],seen=new Set(); let guard=0; while(out.length<n&&guard++<n*25){ const q=genQ(topic,lv); if(seen.has(q.stem)) continue; seen.add(q.stem); out.push(q); } return out; }
function conceptSet(n){ return shuf(CONCEPTS).slice(0,n||CONCEPTS.length).map(conceptQ); }

